-- Stand-in for the AI Buddy Biz project (real column names from the live schema; structure only).
create schema extensions; create extension pgcrypto schema extensions;
do $$ begin create role anon; exception when duplicate_object then null; end $$;
do $$ begin create role authenticated; exception when duplicate_object then null; end $$;
create schema auth;
create table auth.users (id uuid primary key, email text, last_sign_in_at timestamptz);
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('test.uid', true), '')::uuid $$;
create function auth.jwt() returns jsonb language sql stable as $$ select coalesce(nullif(current_setting('test.jwt', true), ''), '{}')::jsonb $$;
create table public.tenants (id uuid primary key, name text, industry_template text, country_code text, base_currency text, plan text, created_at timestamptz default now(), default_tax_code text, tax_registration_no text, tin text, einvoice_enabled boolean, invoice_terms_days integer, legal_name text, company_reg_no text, address text, phone text, email text);
create table public.tenant_modules (tenant_id uuid, module text, enabled boolean, settings jsonb, primary key (tenant_id, module));
create table public.memberships (id uuid, tenant_id uuid, user_id uuid, role_id uuid, outlet_ids text[], active boolean, created_at timestamptz default now());
create table public.roles (id uuid, tenant_id uuid, name text, is_builtin boolean);
create table public.outlets (id uuid, tenant_id uuid, name text, kind text, address jsonb, timezone text, created_at timestamptz, country_code text, region text);
create table public.invites (id uuid, tenant_id uuid, email text, role_id uuid, outlet_ids text[], invited_by uuid, created_at timestamptz default now(), accepted_at timestamptz, accepted_by uuid);
create table public.products (id uuid, tenant_id uuid, category_id uuid, name text, description text, kind text, unit text, tax_code text, image_path text, active boolean, custom_values jsonb, created_at timestamptz, station_id uuid, on_menu boolean, sold_out boolean, menu_sort integer);
create table public.product_variants (id uuid, tenant_id uuid, product_id uuid, sku text, name text, attributes jsonb, price numeric, cost numeric, track_stock boolean, weight_g numeric, hs_code text, active boolean);
create table public.stock_levels (tenant_id uuid, outlet_id uuid, variant_id uuid, qty numeric, reorder_point numeric, bin_location text);
create table public.stock_movements (id bigint, tenant_id uuid, outlet_id uuid, variant_id uuid, qty_change numeric, reason text, unit_cost numeric, ref_type text, ref_id uuid, note text, user_id uuid, at timestamptz);
create table public.sales (id uuid, tenant_id uuid, outlet_id uuid, shift_id uuid, client_sale_id uuid, receipt_no text, status text, customer_id uuid, subtotal numeric, discount_total numeric, tax_total numeric, total numeric, currency text, note text, cashier_id uuid, sold_at timestamptz, synced_at timestamptz);
create table public.shifts (id uuid, tenant_id uuid, outlet_id uuid, user_id uuid, opened_at timestamptz, opening_cash numeric, closed_at timestamptz, counted_cash numeric, expected_cash numeric, note text);
create table public.invoices (id uuid, tenant_id uuid, outlet_id uuid, contact_id uuid, number text, status text, issue_date date, due_date date, currency text, subtotal numeric, discount_total numeric, tax_total numeric, total numeric, amount_paid numeric, notes text, terms text, einvoice_status text, einvoice_uuid text, einvoice_long_id text, einvoice_error text, created_by uuid, created_at timestamptz);
create table public.journal_entries (id uuid, tenant_id uuid, entry_no bigint, entry_date date, memo text, source_type text, source_id uuid, reverses uuid, created_by uuid, created_at timestamptz);
create table public.deals (id uuid, tenant_id uuid, pipeline_id uuid, stage_id uuid, contact_id uuid, title text, value numeric, currency text, source text, owner_id uuid, expected_close date, status text, lost_reason text, score integer, score_reasons jsonb, stage_changed_at timestamptz, closed_at timestamptz, custom_values jsonb, created_at timestamptz);
create table public.lead_capture_log (id bigint, tenant_id uuid, at timestamptz);
create table public.campaigns (id uuid, tenant_id uuid, name text, channel text, filter jsonb, subject text, body text, wa_template text, wa_language text, status text, scheduled_at timestamptz, queued_count integer, sent_count integer, failed_count integer, created_by uuid, created_at timestamptz);
create table public.outbound_messages (id uuid, tenant_id uuid, campaign_id uuid, contact_id uuid, channel text, to_address text, subject text, body text, wa_template text, wa_language text, wa_params jsonb, status text, send_after timestamptz, attempts integer, provider_id text, error text, sent_at timestamptz, created_at timestamptz);
create table public.shipments (id uuid, tenant_id uuid, ref text, mode text, direction text, status text, incoterm text, etd timestamptz, eta timestamptz, customs_status text, dangerous_goods boolean, created_at timestamptz);
create table public.employees (id uuid, tenant_id uuid, user_id uuid, full_name text, status text, created_at timestamptz);
create table public.payroll_runs (id uuid, tenant_id uuid, year integer, month integer, status text, pay_date date, approved_by uuid, approved_at timestamptz, paid_at timestamptz, created_at timestamptz);
create table public.payslips (id uuid, tenant_id uuid, run_id uuid, employee_id uuid, gross numeric, net_pay numeric);
create table public.leave_requests (id uuid, tenant_id uuid, employee_id uuid, status text, created_at timestamptz);
create table public.claims (id uuid, tenant_id uuid, employee_id uuid, status text, amount numeric, created_at timestamptz);
create table public.contracts (id uuid, tenant_id uuid, number text, title text, category text, status text, value numeric, start_date date, end_date date, sent_at timestamptz, signed_at timestamptz, created_at timestamptz);
create table public.compliance_items (id uuid, tenant_id uuid, code text, title text, authority text, category text, due_date date, status text, created_at timestamptz);
create table public.children (id uuid, tenant_id uuid, full_name text, status text);
create table public.kids_incidents (id uuid, tenant_id uuid, child_id uuid, occurred_at timestamptz, kind text, severity text, location text, description text, parent_notified_at timestamptz, guardian_ack_at timestamptz, status text, created_at timestamptz);
create table public.kids_med_given (id uuid, tenant_id uuid, authorisation_id uuid, child_id uuid, given_at timestamptz, dose text);
create table public.orders (id uuid, tenant_id uuid, outlet_id uuid, order_no text, channel text, fulfilment text, status text, items_total numeric, created_at timestamptz, cancelled_at timestamptz, cancel_reason text);
create table public.bookings (id uuid, tenant_id uuid, status text, created_at timestamptz);
create table public.shop_channels (tenant_id uuid, provider text, outlet_id uuid, enabled boolean, import_orders boolean, push_stock boolean, last_order_at timestamptz, last_map_at timestamptz, last_sync_at timestamptz, last_error text, stats jsonb);
create table public.ai_suggestions (id uuid, tenant_id uuid, agent text, kind text, title text, reason text, payload jsonb, status text, created_at timestamptz, decided_at timestamptz, error text);
create table public.ai_usage (id bigint, tenant_id uuid, user_id uuid, feature text, cost_usd numeric, at timestamptz);
